### 6.3 Diagram 业务图模型（MCP读写、持久化存储）

三种图共用同一图容器结构，`nodes` 类型随 `type` 而定，采用**独立强类型节点**定义，业务层**纯语义不含视觉信息**（坐标、形状、颜色一律不进入业务模型）。

```
// 图容器（三种图通用）
interface Diagram {
  diagramId: string;
  type: "architecture" | "class" | "flow";
  metadata: {
    title: string;
    version: number;
    description?: string;
  };
  nodes: ArchitectureNode[] | ClassNode[] | FlowNode[]; // 按 type 对应
  edges: Edge[];
  groups: Group[];
}
```

#### 6.3.1 架构图节点 ArchitectureNode

```
interface ArchitectureNode {
  nodeId: string;
  label: string;                              // 组件显示名称
  layer?: string;                             // 所属层级：接入层/服务层/数据层…
  nodeKind?: "service" | "database" | "mq"
            | "cache" | "external" | "gateway"; // 组件类型
  description?: string;                       // 组件职责说明
  payload?: Record<string, any>;              // 扩展信息：端口、协议、依赖版本等
}
```

#### 6.3.2 类图节点 ClassNode（属性/方法结构化展开）

```
interface ClassNode {
  nodeId: string;
  label: string;                              // 类名
  kind?: "class" | "interface" | "abstract" | "enum";
  attributes?: ClassAttribute[];              // 属性结构化列表
  methods?: ClassMethod[];                    // 方法结构化列表
  description?: string;                       // 类职责说明
}

interface ClassAttribute {
  name: string;
  type: string;
  visibility?: "public" | "private" | "protected";
  static?: boolean;
  description?: string;
}

interface ClassMethod {
  name: string;
  params?: Array<{ name: string; type: string }>;
  returnType?: string;
  visibility?: "public" | "private" | "protected";
  static?: boolean;
  abstract?: boolean;
  description?: string;
}
```

#### 6.3.3 流程图节点 FlowNode

```
interface FlowNode {
  nodeId: string;
  label: string;                              // 步骤名称
  nodeKind?: "start" | "end" | "process"
            | "decision" | "inputOutput" | "subprocess"; // 节点类型
  description?: string;                       // 步骤说明
  payload?: Record<string, any>;              // 扩展信息：判断条件、超时等
}
```

